  "about.pageTitle": "Luminous StockHaven About",
  "about.founderHeading": "📖 About the Founder",
  "about.founder.p1": "Hey there, I'm Concepcion, the founder of Luminous StockHaven.",
  "about.founder.p2": "I don't come from a big tech background, and I don't sit in a corporate office. I'm a small retail owner just like you. I manage five e-commerce storefronts, specializing in books and handmade bookish accessories.\nLike many independent retailers, I hit a breaking point trying to manage multi-location inventory, track publisher ISBNs alongside my own handmade SKUs, and handle supplier orders using clunky spreadsheets. When I looked for an app to help, I tried six different options. Every single one was either completely incomplete, incredibly confusing, or predatory—charging hundreds of dollars a month for basic tools.",
  "about.founder.p3": "Frustrated with an industry that gouges independent creators, I decided to build my own solution. I built Luminous StockHaven out of necessity to run my own businesses cleanly, efficiently, and with total peace of mind.",
  "about.founder.p4": "I decided to open this platform to the public at an honest, affordable price because every small business owner deserves tools that actually work without risking their bottom line. We are independently owned, fiercely protective of our community, and built by a retailer, for retailers.",
