  "upgrade.pastDueTitle": "Payment past due",
  "upgrade.pastDueBody": "Your last payment did not go through, so this subscription is past due. You keep full use for 14 days from the failed payment while you fix it. If it is not fixed, the subscription is cancelled, the workspace becomes view-only for 15 days, and then the account and all its information are deleted. Paying at any point before deletion brings everything back. Update your payment method below. If you need help, email",
