  "upgrade.trialHistoryNote": "If you are paying for Essentials and move to Business, you keep the same customer account and trial history. Business does not include an extra seven-day trial. If you upgrade while your original trial is still running, its original end date does not reset.",
  "upgrade.providerConfirmNote": "Plan changes require confirmation from the billing provider. Any price difference, proration, and effective date must be shown before you approve the change. An upgrade must not create a second simultaneous subscription.",
  "upgrade.chargedThroughProviderNote": "Plan changes are charged through the billing provider. You can cancel your subscription from this page using the Cancel Subscription button under your current plan, or from Settings. Cancelling stops future renewals at the end of your paid period; it never ends your access at once. Existing complimentary workspaces are not charged by viewing these options.",
  "billing.cancel.title": "Cancel subscription",
  "billing.cancel.description": "Unsubscribe from {plan}. Cancelling stops future renewals at the end of your paid period — it never ends your access at once.",
  "billing.cancel.yourPlan": "your plan",
  "billing.cancel.doneTitle": "Your subscription is cancelled.",
  "billing.cancel.doneWithEnd": "You keep full access until {endDate}. After that date you have a {graceDays}-day read-only grace period — you can still log in and see your products, but you cannot add, edit, delete, scan, import, export or change anything. {gracePart}",
  "billing.cancel.graceEndsOn": "After the 15-day grace period ends on {date}, your account and all its information are permanently deleted and cannot be recovered.",
  "billing.cancel.doneNoEnd": "You keep full access until the end of your paid period. After that, a 15-day read-only grace period applies. {wipeSentence}",
  "billing.cancel.refundWindowOpen": "You cancelled within 3 days of your first paid charge, so you may be eligible for a refund of that first payment. Cancelling does not issue the refund itself — request it through {contact}.",
  "billing.cancel.refundWindowClosed": "Cancelling does not by itself issue a refund. Refunds apply only within 3 days of the first successful paid charge, requested through {contact}.",
  "billing.cancel.notCanceledTitle": "Your subscription was NOT cancelled.",
