  "billing.cancel.alreadyCanceledTitle": "This subscription is already cancelled.",
  "billing.cancel.alreadyCanceledWithEnd": "It ends on {date}. You keep full access until then. After that date you have a {graceDays}-day read-only grace period to see your products. {wipeSentence}",
  "billing.cancel.alreadyCanceledNoEnd": "It ends at the end of the current paid period. You keep full access until then.",
  "billing.cancel.appStoreNote": "If you ever subscribe through Google Play or the Apple App Store, you may need to cancel it through that store's subscription settings. This dialog cannot stop app-store billing. Uninstalling the app or deleting your StockHaven account does not cancel a store subscription.",
  "billing.cancel.trialNote": "Cancelling during your trial keeps your full 7 days — access ends on {date}, and you will not be charged.",
