  "exports.eyebrow": "Data",
  "exports.title": "Exports & backups",
  "exports.subtitleStart": "Downloads are always limited to",
  "exports.subtitleRest": ". Every file is labelled with the business name and the date it was made.",
  "exports.createBusinessFirst": "Create a business first — exports belong to a business, not to the app.",
  "exports.lockedTitle": "CSV and Excel exports is a Business feature",
  "exports.lockedDesc": "Your workspace is on the Essentials plan. Business adds CSV and Excel exports, stock valuation, unlimited products and staff, suppliers, purchasing and bundles.",
  "exports.seeBusiness": "See what Business includes",
  "exports.whatTheseAre": "What these files are",
  "exports.about1": "Every dataset comes as CSV or a real Excel workbook (.xlsx) — the full inventory workbook is Excel-only, with one sheet per dataset. CSV files open in Excel, Numbers, Google Sheets and most stock apps. UTF-8 text, quoted commas, line breaks in notes and leading zeroes in codes are all preserved, and cells that start like a formula are neutralised so a spreadsheet opens them as text.",
  "exports.about2": "In the Excel files, SKUs, UPCs, ISBNs and barcodes are text cells — never scientific notation and never trimmed zeroes — with column widths, header filters and currency or quantity formats applied. The full inventory workbook keeps products, stock levels, locations and movements on separate sheets.",
  "exports.about3": "Very large exports stop at 20,000 rows per dataset — when that happens the file name says so (truncated-20000), so a partial file never passes as complete.",
  "exports.about4": "A backup is a snapshot of your data, not a one-click restore. Restoring it is a manual, review-first job, so keep the file safe — nothing in the app can recreate a deleted business from it yet. App code and Base44 platform backups are handled separately from these files.",
  "exports.about5": "Photos and attachments are listed as their stored links — the image files themselves are not packed into the download.",
  "exports.backupTitle": "Full backup",
  "exports.backupDesc": "One file with this business's products, locations, stock levels, complete movement ledger, suppliers, purchasing, orders, returns, counts and listings — plus its profile settings. Keep it somewhere you control.",
  "exports.backupIncludes1": "Products, codes, costs and notes",
  "exports.backupIncludes2": "Locations and per-location quantities",
  "exports.backupIncludes3": "Every movement, with actor and time",
  "exports.backupIncludes4": "Purchasing, orders, returns and counts",
  "exports.buildingBackup": "Building backup…",
  "exports.backupJson": "Backup (JSON)",
