  "import.eyebrow": "Data",
  "import.title": "Import centre",
  "import.subtitleStart": "Three separate spreadsheet operations, so a price correction can never arrive as a stock receipt. Everything lands in",
  "import.subtitleRest": " only, and nothing is written until a dry run has passed.",
  "import.createBusinessFirst": "Create a business first — imported products belong to a business.",
  "import.createBusinessFirstShort": "Create a business first.",
  "import.whatEachDoes": "What each operation does",
  "import.createTitle": "Create new products",
  "import.createDesc": "adds rows that are not in the catalogue yet. Duplicate SKUs and barcodes already in use are skipped, and opening stock can land in a location you choose as a receipt.",
  "import.updateTitle": "Update existing products",
  "import.updateDesc": "matches each row by SKU or record ID and shows the old value beside the proposed new one. Blank cells leave the saved value alone unless you ask for blanks to be cleared, and quantities are never touched.",
  "import.receiveModeTitle": "Receive stock",
  "import.receiveModeDesc": "adds arriving quantities to one location and writes a receipt to the movement ledger for every line. Each batch is marked, so the same sheet cannot be received twice.",
  "import.excelNote": "Excel workbooks (.xlsx) are read directly — pick the worksheet and the columns are matched for you. Codes stay whole: a UPC saved as text keeps its digits and leading zeroes. Rows that cannot be imported are listed with a reason",
