  "print.supplierBlockedDesc": "Supplier documents go with the Business plan — suppliers, purchasing and purchase orders. Everything you have now keeps working.",
  "print.seeBusiness": "See what Business includes",
  "print.nothingToPrint": "Nothing to print yet",
  "print.pickOrderHint": "Pick a purchase order from the list to preview the document.",
  "print.pickCustomerOrderHint": "Pick a customer order from the list to preview the document.",
  "print.pickReturnHint": "Pick a logged return from the list to preview the document.",
  "print.chooseStyleHint": "Choose a style, then pick products from the list. The preview shows exactly what comes out of the printer.",
  "print.howToReach": "How to reach your printer",
  "print.howIntro": "This app connects to printers you already own — it is not a printer itself. There are four ways to reach one, and labels print on both plans over any of them. Packing slips, purchase orders, supplier documents and reports are Business-only, whatever the connection.",
  "print.howBluetoothLead": "Bluetooth.",
  "print.howBluetoothBody": "From this page, on desktop Chrome or Edge and on Android Chrome: pick your label printer and the labels go straight to it. It does not work in iOS Safari — on an iPhone, Bluetooth printing comes with the mobile app instead. A printer that only speaks Zebra ZPL or Brother’s own language will not understand the labels this page sends; that is checked against real printers before it is called working.",
  "print.howWifiLead": "Wi-Fi.",
  "print.howWifiBody": "Install the printer on your shop’s Wi-Fi, then use the Print button — it prints through the printer installed on this computer, over the shop network. On an iPhone, AirPrint is built in: an AirPrint printer on the same Wi-Fi just appears in the print sheet, no cable and no app needed, and the app needs no AirPrint-specific code. The printer must support AirPrint (most new ones do) and the phone and printer must be on the same Wi-Fi.",
  "print.howEthernetLead": "Ethernet.",
  "print.howEthernetBody": "Wire the printer to your shop network with an Ethernet cable, install it on the computer, and print through the Print button. Ethernet is a desktop and computer path — iPhones do not use Ethernet cables.",
  "print.howUsbLead": "USB.",
  "print.howUsbBody": "Plug the printer into the computer with its cable and use the Print button — it prints through the printer installed there. On an Android phone with a USB OTG cable, the USB button above talks straight to the printer. iPhones cannot print over USB directly — no WebUSB there — so use Wi-Fi / AirPrint, or Bluetooth from the mobile app.",
  "print.howCordsLead": "Cables still serve iPhones, one step removed.",
  "print.howCordsBody": "A USB printer plugged into the shop computer, or an Ethernet printer wired to the network, shows up on your iPhone over the shop Wi-Fi (AirPrint / shared printer) — the cables put the printer on the network solidly, and the phone reaches it wirelessly.",
  "print.howOfflineLead": "If the internet drops,",
  "print.howOfflineBody": "the labels and documents already on this page still print — the Print button, the Labels PDF, Bluetooth and USB need no connection. What does need the internet is loading the page and its products in the first place. Full offline mode (working in the app with no connection at all) is a separate, bigger build and is not claimed here.",
