  "settings.cancelTerms.appleLink": "Apple cancellation instructions",
  "settings.cancelTerms.googlePlayLink": "Google Play cancellation instructions",
  "settings.cancelTerms.graceTitle": "After your paid period ends — 15-day grace, then deletion:",
  "settings.cancelTerms.intro": "These are the terms for paid Luminous StockHaven subscriptions. Website subscription billing is through Stripe. You can cancel your subscription yourself at any time using the Cancel Subscription button below — no staff approval is needed. Cancellation and refund requests can also be handled through the official customer support contact, theluminousbookshop@outlook.com.",
  "settings.cancelTerms.noApprovalBody": "You may cancel your subscription yourself at any time. No staff approval is required. Future renewals stop only after the billing provider confirms cancellation.",
  "settings.cancelTerms.noApprovalTitle": "Cancel without approval:",
  "settings.cancelTerms.paymentBody": "For paid trials, the seven-day trial requires a payment method at signup. Unless cancelled within the applicable trial cancellation deadline, the selected monthly plan will be charged automatically after the trial. The price, first billing date, and provider-specific cancellation deadline must be shown during signup. Trial billing is through Stripe.",
  "settings.cancelTerms.paymentTitle": "Payment method and automatic renewal:",
  "settings.cancelTerms.remainingBody": "If you have already paid for a billing period, you may retain access until that verified paid-through date. Earlier termination requires appropriate provider confirmation and any applicable refund handling. Free-trial access ends according to the provider-confirmed trial termination date.",
  "settings.cancelTerms.remainingTitle": "Remaining access:",
  "settings.cancelTerms.storesBody": "If you ever subscribe through Google Play or the Apple App Store, your subscription is billed and managed by that store. You may need to cancel it directly in the subscriptions section of the same Google or Apple account used to subscribe. Cancelling a separate website subscription, uninstalling this app, or requesting Luminous StockHaven account deletion does not automatically cancel a store-billed subscription. Check your purchase receipt to confirm who bills you.",
  "settings.cancelTerms.storesTitle": "Google Play and Apple App Store subscriptions (if you ever subscribe through a store):",
  "settings.cancelTerms.title": "Cancellation Terms & Conditions",
  "settings.cancelTerms.trialBody": "The seven-day trial can be used only once per eligible customer. Cancelling a trial or subscription does not grant another trial; returning customers must choose a paid subscription.",
  "settings.cancelTerms.trialTitle": "One free trial:",
  "settings.canceled.endsOn": "This subscription is cancelled and ends on {date}. You keep full access until then.",
  "settings.delete.checking": "Checking for an existing deletion request…",
  "settings.delete.description": "Request removal of your Luminous StockHaven sign-in account.",
  "settings.delete.dialogDescription": "This requests a review of account deletion. It does not immediately remove your login or inventory, and it does not cancel any Stripe subscription. Type {word} to confirm you want to submit the request.",
  "settings.delete.dialogTitle": "Request Account Deletion",
  "settings.delete.enterDelete": "Enter {word} to confirm",
  "settings.delete.exportFirst": "Export your inventory first if you need to keep your records.",
  "settings.delete.intro": "Submitting a request does not immediately delete your account, businesses, or inventory. Requests are reviewed separately before deletion can be completed. This request does not cancel a Stripe subscription or stop future billing; subscription cancellation must be handled separately through the billing provider.",
  "settings.delete.keepAccount": "Keep Account",
  "settings.delete.noExport": "Essentials has no export — write down anything you need before requesting deletion.",
  "settings.delete.notDeleted": "Your account and data have not been deleted by this request. Billing has not been cancelled.",
  "settings.delete.received": "Your account deletion request has been received.",
