  "settings.details.address": "Address",
  'settings.details.taxRate': 'My tax rate',
  'settings.details.taxRateHint': 'Set it once. Every new sales order fills in its own tax from this rate — you can still change the tax on any single order.',
  "settings.details.taxMode": "How orders get their tax",
  "settings.details.taxModeFixed": "My fixed rate",
  "settings.details.taxModeAutomatic": "Automatic — by the customer's state",
  "settings.details.taxModeHint": "Fixed uses your rate on every new order. Automatic fills a new order's tax from the customer's state base rate the moment the state is on the order, and refills it if the state changes. These are state base rates — local taxes may add more. An order with no state, or outside the US, uses your fixed rate above.",
  'settings.details.gs1Prefix': "GS1 company prefix",
  'settings.details.gs1PrefixHint': "Only if you license a prefix from GS1. Set it once and the product form’s code generator can mint true retail UPC and EAN codes from your own numbers — each one used only once, never reused. Leave it blank if you do not have one; the app never invents a prefix.",
