  "settings.trial.cancelKeeps": "Cancelling during your trial keeps your full 7 days — access ends on {date}, and you will not be charged.",
  "staff.access.noSeatBody": "Your account has no staff seat for this business, so its stock stays closed. Ask the owner to add you in Staff & roles.",
  "staff.access.noSeatTitle": "This business is not open to your login",
  "staff.access.pendingBody": "This business has an invitation for your email that has not been activated. Ask the owner to set your staff status to active. Nothing here is visible until then.",
  "staff.access.pendingTitle": "Your invitation is not active yet",
  "staff.access.signOut": "Sign out",
  "staff.access.suspendedBody": "An administrator has suspended this staff account for the active business. Ask them to set you back to active, then sign in again.",
  "staff.access.suspendedTitle": "Your access is paused",
  "staff.addFirst": "Add the first staff member",
  "staff.addMember": "Add staff member",
  "staff.emptyBody": "Add a person, give them a role and the permissions that go with it, and they are invited by email to sign in to this business.",
  "staff.emptyTitle": "No staff yet",
  "staff.eyebrow": "Team",
  "staff.how.p1": "Every member has a role and their own permission list, so you can start from a role and change one thing without making a new role. Editing a role does not rewrite the members already on it — open a member to re-apply their role defaults.",
  "staff.how.p2": "Custom roles are a Business feature: Essentials uses the five built-in roles (Owner, Manager, Stock clerk, Sales clerk, Viewer).",
  "staff.how.p3": "Invitations are sent by email. A member can only sign in once they accept, and removing someone from this list does not delete their app account.",
  "staff.how.p4": "A store is the location a person is assigned to. It is recorded on their card; what they can open is still decided by their role and permissions.",
  "staff.how.p5": "Permissions decide what each person can open: menu items outside their role are hidden, and a blocked address shows a “not on your role” notice instead of the page. A change applies the next time that person loads the app; suspending a member locks them out entirely.",
  "staff.how.p6": "Administrators can see and change all data, manage app users and roles, and are never limited by a staff role. Someone with no staff record — the owner of a new business — keeps full access.",
  "staff.howTitle": "How staff and roles work",
