  "training.lessons.owner-shipping-labels.step1": "The Print Center carries a Shipping label style on both plans: pick a customer order and print a 4×6 label with the buyer’s name and address and your business as the sender.",
  "training.lessons.owner-shipping-labels.step2": "The label is white-label, like every customer document: it carries your business name only — never the name of this app — so a parcel from your store looks like it came from your store.",
  "training.lessons.owner-shipping-labels.step3": "The customer's address is kept with their orders for 90 days after their last order, and the label starts from the order's stored address when it has one; an address typed at print time for a one-off label is not saved back. The name still fills in from the order so the label matches the paperwork.",
  "training.lessons.owner-shipping-labels.step4": "The label prints through the same four connections as every label — Bluetooth, Wi-Fi, Ethernet and USB — and a 4×6 thermal printer is the standard size for it.",
  "training.lessons.owner-shipping-labels.step5": "Bought the postage from the carrier instead? In this same section you can upload the carrier's label file — PDF, PNG or JPG — and it stays saved on the order for good: your record, on hand just in case something happens. It prints at its true 4×6 size. The app never sells postage, so the carrier's price is the only price — and always the right one.",
  "training.lessons.owner-shipping-labels.title": "Shipping labels for customer orders",
  "training.lessons.print-shipping-label.step1": "When an order is ready to send, open the Print Center and choose the Shipping label style, then pick the customer order. The buyer’s name fills in from the order.",
  "training.lessons.print-shipping-label.step2": "Check the address the parcel is going to. When the order carries the customer's address — kept for 90 days after their last order — it fills in for you; an address you type at print time is not saved back, so check the postcode and the last line carefully before you print.",
  "training.lessons.print-shipping-label.step3": "Your own business name prints at the top as the sender. If you want your address on the label too, type it in the sender address box — leave it empty if you would rather it not appear.",
  "training.lessons.print-shipping-label.step4": "Print on a 4×6 label — a thermal label printer is the usual fit — or on any printer through the browser print button. Stick the label flat on the parcel, where it will not fold over an edge.",
  "training.lessons.print-shipping-label.step5": "If the postage was bought from the carrier, save their label file on the order instead: upload the PDF, PNG or JPG the carrier gave you in the Your carrier label section. It stays on the order as your record and prints at its true 4×6 size — and the app's own address label is always there when you would rather use it.",
  "training.lessons.print-shipping-label.title": "Print a shipping label",
