  "apiErrors.notFound.voiceNoteFound": "Voice note not found.",
  "apiErrors.invalidValue.sendVoiceRecording": "Send a voice recording of a few minutes at most.",
  "apiErrors.invalidValue.recordingNotPrepared": "That recording could not be prepared — please record it again.",
  "training.lessons.messages-private.step5": "You can also send a voice note: tap the microphone beside the message box, talk, and tap stop. Listen to it first — then send it, or delete it and record again. When someone sends you one, tap play to hear their real voice.",
  "training.lessons.owner-messages-oversight.step5": "Read marks: when a team member reads a message you sent them, you see it marked read. Staff and managers see each other's read marks the same way, both directions.",
  "training.lessons.owner-messages-oversight.step6": "Your own reading is invisible. When you read a message a staff member sent you, they never see a read mark — and you do not need to tell your team that their conversations are saved in the app and that you, the owner, can read them. That oversight is part of looking after your store.",
  "training.lessons.owner-messages-oversight.step7": "What you do about negative messages between staff members is up to you. Let it pass, speak to someone quietly, or act on it — the choice is yours, and you never have to say where you saw it.",
