  "settings.policies.title": "Store policies & terms",
  "settings.policies.ownerDescription": "Your store, your rules. Write your store policies and your terms & conditions here — type them in, or upload a file. Every new team member sees them once when they start, and everyone on your team can read them here any time. Only you can change them.",
  "settings.policies.memberDescription": "Your store's own policies and terms, written by the owner. Only the owner can change them.",
