  "settings.platformPolicies.title": "Luminous StockHaven policies",
  "settings.platformPolicies.description": "The app's own terms and policies. They stay with the app, and everyone on the team can read them here.",
  "staffWelcome.policiesIntro": "Before you start: your store's policies and terms, written by the owner.",
  "plansLib.includes.storePolicies": "Your own store policies and terms in Settings, for your whole team to read",
  "apiErrors.businessPoliciesOwnerOnly": "Only the owner can change this store's policies and terms.",
  "apiErrors.policyFileInvalid": "Send a PDF, text, Word or OpenDocument file under 25 MB.",
  "apiErrors.policyTextTooLong": "That document is too long to type here. You can upload it as a file instead.",
  "training.lessons.owner-store-policies.title": "Your store policies & terms",
  "training.lessons.owner-store-policies.step1": "Open Settings for the Store policies & terms card. It holds two documents: your Store Policies — the house rules for your store — and your Terms & Conditions.",
  "training.lessons.owner-store-policies.step2": "Each document can be typed right there, or uploaded as a file (a PDF, text, Word or OpenDocument file, up to 25 MB). It is one or the other: saving text replaces a file, and uploading a file replaces the text. Removing a document clears it.",
  "training.lessons.owner-store-policies.step3": "Your team sees both documents once, on their welcome page when they first start, and can read them any time in their Settings. They are read-only for your team — only you can write or change them.",
  "training.lessons.owner-store-policies.step4": "Each business keeps its own documents: what you write here belongs to this store alone and never appears in another business. Luminous StockHaven's own terms and policies live beside yours in Settings, and everyone can read those too.",
  "training.lessons.welcome-basics.step5": "Your store's policies and terms are shown once on your welcome page, and they live in Settings, where you can read them any time.",
  "apiErrors.policyDocNotFound": "That document is not one of the two.",
  "apiErrors.policyFileNotFound": "No file is saved for that document.",
  "staffLib.perm.staffRoster": "See the full staff roster",
  "staffLib.area.staffAccess": "Staff roster",
  "staff.memberDialog.staffAccessHint": "Managers only — with this tick, this manager sees the full staff roster, read-only. Without it, a manager sees only their own card. This tick does nothing for staff.",
  "workforce.schedule.clear": "Clear",
  "workforce.messages.charCount": "{count} of {max} characters",
  "workforce.messages.charLimit": "That's the limit for one message — nothing more will fit.",
  "staffLib.perm.alertsView": "See low-stock alerts",
  "staffLib.perm.productsReorder": "Change reorder points",
  "staffLib.area.lowStockAccess": "Low stock",
  "staff.memberDialog.lowStockAccessHint": "With the first tick, this person sees the low-stock alerts — the Needs attention box, the Low stock page and the LOW marks. With the second tick, they can change a product’s reorder point; without it, the Reorder at box still shows, but a change to it will not save.",
  "apiErrors.reorderChangeReserved": "Only the owner, or a team member the owner has allowed to change reorder points, can change a reorder point.",
  "apiErrors.alertsViewReserved": "Only the owner, or a team member the owner has allowed to see low-stock alerts, can see low-stock alerts.",
  "apiErrors.quizRequired": "This lesson finishes with a short quiz — answer it correctly to complete the lesson.",
  "apiErrors.trainingIncomplete": "Not yet — this person still has training to finish.",
  "settings.policyQuiz.addMc": "Add a multiple-choice question",
  "settings.policyQuiz.addOpen": "Add an open question",
  "settings.policyQuiz.correct": "Correct",
  "settings.policyQuiz.empty": "No questions yet. With no questions, this training is just the reading.",
  "settings.policyQuiz.expected": "Expected answer",
  "settings.policyQuiz.expectedHint": "The answer you expect, in your words. An answer that matches nearly word for word counts as correct on the spot; the rest come to you for a look.",
  "settings.policyQuiz.hint": "Write questions about this document for your team. A person answers them in Training when you tick this training for them in their Staff record. There is no limit on how many questions you write.",
  "settings.policyQuiz.mcLabel": "Multiple choice",
