  "settings.policyQuiz.passLine": "Passing line",
  "settings.policyQuiz.passLineHint": "The score — counting multiple-choice answers only — a person needs to finish this training.",
  "settings.policyQuiz.question": "Question",
  "settings.policyQuiz.remove": "Remove",
  "settings.policyQuiz.save": "Save questions",
  "settings.policyQuiz.saved": "Questions saved.",
  "settings.policyQuiz.title": "Questions for your team",
  "staff.memberDialog.trainingAccessHint": "Reading the store policies and terms is for everyone. These ticks assign the quiz training the owner builds beside each document in Settings.",
  "staffLib.area.trainingAccess": "Policy quiz trainings",
  "staffLib.perm.trainingPoliciesQuiz": "Store Policies quiz training",
  "staffLib.perm.trainingTermsQuiz": "Terms & Conditions quiz training",
  "training.comment.placeholder": "Anything about this lesson…",
  "training.comment.send": "Send comment",
  "training.comment.sent": "Your comment was filed to the owner.",
  "training.comment.title": "Leave a comment for the owner",
  "training.lessons.download-app.step1": "Luminous StockHaven can live on your phone or computer like a real app — no app store needed.",
  "training.lessons.download-app.step2": "Open Settings and find the Download the app card. It is there for every role, on both plans.",
  "training.lessons.download-app.step3": "Tap the install button and follow your device's prompt. The app lands on your home screen with the store's name and icon.",
  "training.lessons.download-app.step4": "Open it from your home screen from then on — it signs you in the same way and shows the same store.",
  "training.lessons.download-app.title": "Download the app to your device",
  "training.lessons.mgr-tax-rate.step1": "Orders can carry a sales tax rate. The owner sets the rate itself in Settings; it is one rate for the whole store.",
  "training.lessons.mgr-tax-rate.step2": "When the owner ticks the tax section for you in your Staff record, the rate appears in your Settings too, and you can keep it up to date there.",
  "training.lessons.mgr-tax-rate.step3": "The rate is a percent — 8.25 means the customer pays 8.25% tax on top of the order's goods.",
  "training.lessons.mgr-tax-rate.step4": "When the rate changes, new orders use the new rate. Orders already placed keep the rate they were made with.",
  "training.lessons.mgr-tax-rate.step5": "If the owner switches tax to Automatic, a new order fills its tax from the customer's state base rate as soon as the state is on the order, and refills if the state changes. These are state base rates; local taxes may add more. An order with no state, or outside the US, uses the store's fixed rate — and a tax typed on an order still wins.",
  "training.lessons.mgr-tax-rate.title": "The store's tax rate",
  "training.lessons.owner-confidentiality.step5": "Here is the whole map. Your team sees their own work — their schedule, their tasks, their pay stubs, their messages, and the store screens their role opens. They never see your trial, which plan the business is on, what the plan costs, whether a payment went through, or that a plan limit was reached. Money surfaces — billing, invoices, payment methods — are owner-only, always.",
  "training.lessons.owner-confidentiality.step6": "If the account is ever stopped, this is the exact message your team sees: “Changes are turned off right now. Nothing can be added or changed at the moment — please ask the owner of the business if you need anything.” Nothing in it names a plan, a price, or a payment.",
  "training.lessons.owner-confidentiality.step7": "And when a plan limit is what stops something, this is the exact message: “That can't be added right now — please ask the owner of the business.” It never says a limit was reached — that stays between you and the app.",
  "training.lessons.staff-builds.step1": "A build puts products together into one sellable thing — a bundle, a kit, a gift set. Builds live in the Builds screen in the menu.",
  "training.lessons.staff-builds.step2": "Open a build to see what goes into it: each part product and how many of each the build uses.",
  "training.lessons.staff-builds.step3": "When a build is made or sold, the stock of its parts moves with it — the app keeps the counts honest for you.",
  "training.lessons.staff-builds.step4": "If a part is missing or a count looks wrong, tell your manager rather than guessing — builds touch many products at once.",
  "training.lessons.staff-builds.title": "Builds and bundles",
  "training.lessons.staff-cross-store.step1": "When your business has more than one store or site, the stores can ask each other for stock. Those requests land in the cross-store inbox.",
  "training.lessons.staff-cross-store.step2": "Open the inbox from the menu to see what another store is asking for, and what your store has been sent.",
  "training.lessons.staff-cross-store.step3": "Answer a request only the way your manager has shown you — sending stock out changes your own store's counts.",
  "training.lessons.staff-cross-store.step4": "If a request looks wrong — the wrong item, or more than you have — do not guess. Flag it to your manager.",
  "training.lessons.staff-cross-store.title": "The cross-store inbox",
  "training.lessons.staff-reports.step1": "Reports gather the store's numbers — sales, stock and more — into one place. Reports live in the menu.",
  "training.lessons.staff-reports.step2": "Open a report to see its numbers for the dates it covers. The dates are part of the report: the same report over a different week tells a different story.",
  "training.lessons.staff-reports.step3": "Some reports can be saved out of the app as files. Only save a report out when your manager or the owner has asked for it.",
  "training.lessons.staff-reports.step4": "Report numbers come from the store's real work — orders, counts and movements — so honest entries everywhere else keep the reports true.",
  "training.lessons.staff-reports.title": "Reading the reports",
  "training.lessons.welcome-basics.step6": "When you are done, sign out: a Sign out link sits at the very bottom of every page, just above the copyright line. Signing out signs you out everywhere, on every device — so nobody can wander into your account on a shared screen.",
