  "training.lessons.your-profile-photo.title": "Your profile photo",
  "training.lessons.your-profile-photo.step1": "Your photo appears beside your name at the top of the app, on the Staff page, and beside your messages — once the owner has approved it. Until then, only your initials show.",
  "training.lessons.your-profile-photo.step2": "Open Settings and find Your profile photo. Choose a photo of yourself and send it. It goes to the owner to approve — it does not appear anywhere while it waits.",
  "training.lessons.your-profile-photo.step3": "When the owner approves it, your bell rings and your photo starts showing. If it is not approved, choose a different photo and send that one instead.",
  "training.lessons.your-profile-photo.step4": "Changing your photo works the same way: the new one waits for approval, and your current photo stays in place until the new one is approved. If a change is not approved, you keep your other one.",
  "training.lessons.owner-profile-photos.title": "Profile photos and your name",
  "training.lessons.owner-profile-photos.step1": "Every person's photo shows beside their name at the top of the app, on your Staff page, and beside their messages. A team member's photo appears nowhere until you approve it — approval is yours alone, and nobody can approve their own photo.",
  "training.lessons.owner-profile-photos.step2": "When someone sends a photo, your bell rings. Open the Staff page to see it, then choose Approve or Not approve. If you do not approve it, the person is told to choose another photo.",
  "training.lessons.owner-profile-photos.step3": "If a person changes their photo, the new one waits for your approval the same way. Their current photo stays in place while it waits — and stays if you do not approve the change.",
  "training.lessons.owner-profile-photos.step4": "Your own photo needs no approval: set it in Settings, under Your profile photo. The same card holds your name — the name you set there replaces the word Owner everywhere your team sees it, in the app and in Messages.",
