  "training.lessons.mgr-clock-callin.title": "Call-ins and clock corrections",
  "training.lessons.mgr-clock-callin.step1": "The owner can give a manager two separate ticks. Call-ins lets you open a call-in window for a staff member, and Clock board & missed clock-outs lets you see the team’s clock board and correct time entries from the Staff page. Each tick works on its own — a manager can hold one without the other.",
  "training.lessons.mgr-clock-callin.step2": "A call-in window lets one person sign in and clock in when no shift covers them. Open it from the Staff page, on the Call-ins & missed clock-outs card.",
  "training.lessons.mgr-clock-callin.step3": "The window stays open until that person clocks out — the usual 10-minute sign-out grace follows — or until you or the owner close it early. Nothing closes it on its own.",
  "training.lessons.mgr-clock-callin.step4": "When someone forgets to clock out, their entry is flagged on the Staff page and in Payroll once the scheduled shift has ended, and you and the owner are belled. The entry keeps counting until it is corrected.",
  "training.lessons.mgr-clock-callin.step5": "Correct the entry from the Staff page: set the clock-in, the clock-out, and any break times. A manager corrects staff entries only — a manager’s own entries are the owner’s to fix.",
  "staffLib.perm.staffDocuments": "Staff documents",
  "staffLib.area.documentsAccess": "Staff documents",
  "staff.memberDialog.documentsAccessHint": "Managers only — with this tick, this manager can open staff members' document files: the paperwork kept for each person, like W-4s, job applications and ID copies. You will be asked to confirm first — these files hold Social Security numbers and dates of birth. This tick does nothing for staff.",
  "staff.documentsWarning.body": "This person will be able to see confidential information about your staff members, including Social Security numbers and dates of birth.",
