  "nav.xstoreMessages": "Cross-store messages",
  "plansLib.businessIncludes.xstoreMessages": "Cross-store messages — your whole team, across every business",
  "xstore.title": "Cross-store messages",
  "xstore.help": "Everyone on this account, across all your businesses, in one inbox. Message any of them here — text or voice, with delivery and read marks. Your in-store Messages stay as they are.",
  "xstore.empty": "No conversations yet. Start one with New message.",
  "xstore.noPeople": "There is nobody else to message yet. People appear here once they join one of your businesses and sign in.",
  "xstore.deliveredLabel": "Delivered",
  "apiErrors.planGated.crossStoreMessagesPartBusiness": "Cross-store messages are part of the Business plan.",
  "apiErrors.invalidValue.personNotPartAccount": "That person is not part of this account.",
  "training.lessons.owner-xstore-messages.title": "Messages across your stores, for owners",
  "training.lessons.owner-xstore-messages.step1": "Cross-store messages is a second inbox, separate from Messages. Messages is for the store you are standing in; this door reaches everyone on your account, in every business you own — up to five.",
  "training.lessons.owner-xstore-messages.step2": "Open Cross-store messages from the menu and start a conversation with anyone on the list. The list shows every team member across all your businesses who has signed in, with the stores they work in.",
  "training.lessons.owner-xstore-messages.step3": "Photos ride along: each person shows their approved profile photo, or their initials when they have none. Every message carries the date and time it was sent.",
  "training.lessons.owner-xstore-messages.step4": "Under your own messages you can see Delivered once a message lands, and Read once the other person opens the conversation. Voice notes work here too, exactly like in Messages.",
  "training.lessons.owner-xstore-messages.step5": "Conversations here are private to the two people in them. Your in-store Messages oversight does not reach across stores.",
  "training.lessons.mgr-xstore-messages.title": "Messages across your stores, for managers",
  "training.lessons.mgr-xstore-messages.step1": "Cross-store messages reaches everyone on this account, across every business — not just the store you are standing in. It sits in the menu, separate from Messages.",
  "training.lessons.mgr-xstore-messages.step2": "Start a conversation from the list: every team member who has signed in is there, with the stores they work in beside their name.",
  "training.lessons.mgr-xstore-messages.step3": "Send text, or record a voice note. Before a voice note sends, you can listen back, toss it, or send it — the same as in Messages.",
  "training.lessons.mgr-xstore-messages.step4": "Your messages show Delivered when they land and Read when the other person opens the conversation. The photo beside each name is that person's approved profile photo.",
  "training.lessons.staff-xstore-messages.title": "Messages across your stores",
  "training.lessons.staff-xstore-messages.step1": "Cross-store messages is where you can reach anyone on this account, in any of the owner's businesses — a question for another store no longer has to wait.",
  "training.lessons.staff-xstore-messages.step2": "Open it from the menu, pick the person, and write. If the person you need is not listed, they have not signed in yet — they appear as soon as they do.",
  "training.lessons.staff-xstore-messages.step3": "You can send voice notes here too: record, listen back, then send or toss it. Every message shows the date and time it was sent.",
  "training.lessons.staff-xstore-messages.step4": "When you send a message it shows Delivered once it lands, and Read once the other person opens the conversation. A conversation is private to you and the other person.",
