  "training.lessons.owner-restaurant-ops.title": "Restaurant operations, for owners",
  "training.lessons.owner-restaurant-ops.step1": "Supplier invoices live in the Restaurant corner. Enter what a supplier billed, linked to its purchase order, and the app checks it three ways — ordered, received and invoiced, side by side — and flags any line that is short, over, or billed at a different price.",
  "training.lessons.owner-restaurant-ops.step2": "When an invoice line bills a product at a price different from the cost on record, a price alert opens on the invoices page. Accepting an alert updates the product's cost to the billed price; dismissing it leaves the cost as it was.",
  "training.lessons.owner-restaurant-ops.step3": "The waste log records everything the kitchen throws away, with a reason — spoilage, overproduction, a prep mistake, a return, spillage, or other — and logging it takes the stock off the shelf by itself. Expiry batches are listed first-expired, first-out, so the earliest use-by date gets used first, and you can print date labels for the batches you tick.",
  "training.lessons.owner-restaurant-ops.step4": "The allergen matrix works out every dish's allergens from its recipe's ingredients, against the nine major allergens, so a guest's question is answered from the record, not from memory. Temperature logs, the 86 board and staff meals are open to the whole team — no tick needed — because daily logging only works when anyone can do it.",
  "training.lessons.owner-restaurant-ops.step5": "Menu engineering places each dish by how much it sold and how much it earned: stars, plowhorses, puzzles and dogs. The variance page compares what the recipes say should have left the shelf against staff meals, waste and everything else that went out — what is left over is unexplained. The accounting export gathers purchases received, waste, staff meals and recipe depletion into one ledger for your books.",
  "training.lessons.staff-restaurant-daily.title": "The kitchen's daily habits",
  "training.lessons.staff-restaurant-daily.step1": "When something is thrown away, log it in the waste log the same day: what it was, how much, and the reason — spoilage, overproduction, a prep mistake, a return, spillage, or other. Logging it takes the stock off the shelf by itself; you do not adjust the stock separately.",
  "training.lessons.staff-restaurant-daily.step2": "Log each fridge, freezer and hot-holding temperature as you check it. The log keeps your name and the time, and flags any reading outside the safe range — write down what you did about it as the corrective action.",
  "training.lessons.staff-restaurant-daily.step3": "The 86 board is what is out, right now. Post an item the moment it runs out, so the whole team knows at once, and clear it when it is back — the board keeps who cleared it and when.",
  "training.lessons.staff-restaurant-daily.step4": "When the team eats, record it as a staff meal. Each meal takes its dish off the shelf and uses the dish's recipe ingredients, the same as a sale. A staff meal is a real cost of the day, and it belongs on the record.",
  "training.lessons.mgr-restaurant-invoices.title": "Invoices, batches and batch runs",
  "training.lessons.mgr-restaurant-invoices.step1": "The owner has trusted you with the Build recipes tick, and it also opens the kitchen's building work: supplier invoices, expiry batches and batch production. Enter a supplier invoice with its lines — the product, the quantity and the billed cost — and link it to its purchase order when there is one.",
  "training.lessons.mgr-restaurant-invoices.step2": "With a purchase order linked, the invoice is checked three ways, line by line: what was ordered, what was received and what was invoiced. A line can come back matching, short, over, billed at a different price, or not on the order at all.",
  "training.lessons.mgr-restaurant-invoices.step3": "When a billed price differs from the product's cost on record, a price alert opens. Accepting the alert sets the product's cost to the new billed price; dismissing it changes nothing. Only one open alert stands for the same invoice and product at a time.",
  "training.lessons.mgr-restaurant-invoices.step4": "Receive stock as an expiry batch with its use-by date, and the expiry page keeps the batches first-expired, first-out. A batch run makes a recipe a set number of times: it uses up the recipe's ingredients and puts the finished prep product on the shelf — the recipe must be linked to that prep product first.",
  "training.lessons.mgr-restaurant-invoices.step5": "When a supplier gives money back against an invoice — a damaged case, a short delivery, a price made right — record it as a credit memo on the invoices page, against that invoice. The supplier comes from the invoice itself, and the memo counts against what the invoice is still owed: the invoice shows its credit applied and its balance due. A credit can never be more than its invoice, and voiding a memo keeps it on the record while it stops counting. Print the memo from its row when you need it on paper — the printed sheet is your own record of the supplier's credit, not the supplier's document.",
  "training.lessons.mgr-restaurant-reports.title": "Menu engineering, variance and the books",
  "training.lessons.mgr-restaurant-reports.step1": "The owner has trusted you with the Dish money tick, and it also opens the kitchen's money reports: menu engineering, variance and the accounting export. These figures stay inside the business, like all dish money.",
  "training.lessons.mgr-restaurant-reports.step2": "Menu engineering places every dish by how much it sold and how much it earned in the period. Stars sell well and earn well; plowhorses sell well but earn little; puzzles earn well but sell little; dogs do neither.",
  "training.lessons.mgr-restaurant-reports.step3": "The variance page works per product: what the recipes say should have left the shelf, beside staff meals, waste and every other stock-out. Whatever is left over is unexplained — and unexplained is the number to go and explain.",
  "training.lessons.mgr-restaurant-reports.step4": "The accounting export is one ledger for the kitchen: purchases received, waste, staff meals and recipe depletion, each row with its date, quantity and cost, ready to hand to whoever keeps your books.",
