  "plansLib.includes.recordPrints": "Record prints — weekly schedule, payroll register, timesheet, training record, policies & terms, staff roster and price list, printed filled or blank to fill in by hand",
  "training.lessons.staff-record-prints.title": "Your records on paper",
  "training.lessons.staff-record-prints.step1": "Almost every record in the app now has a paper twin in the Document Style Studio: the weekly schedule, the payroll register, the timesheet, the training record, your store policies & terms, the staff roster and the product & price list — and on the Business plan, the supplier directory and the filled temperature log. Each one prints in your saved document style, in your business's language, with your dates written your way.",
  "training.lessons.staff-record-prints.step2": "Find each paper where its record lives. On the Workforce page, the Schedule tab prints the week for everyone you can see, and the Time Clock tab prints the timesheet from its entries. A print only ever shows what you can already see on that screen — printing never widens anyone's view.",
  "training.lessons.staff-record-prints.step3": "On the Payroll page, preview a pay period and print the register: every person, their hours, gross, deductions and net on one sheet for the wage file. On the Training page, the team section prints the training record — who finished what, with quiz scores and dates.",
  "training.lessons.staff-record-prints.step4": "Your store policies & terms print from Settings, exactly as you wrote them, ready for a new hire's hand or the wall. The Staff page prints the one-page roster, the Products page prints the price list, and on Business the Suppliers page prints the directory and the Temperature logs page prints the filled log for the food-safety file.",
  "training.lessons.staff-record-prints.step5": "Need a sheet to fill in by hand instead? The Print Center's blank forms now carry a blank twin of every one of these papers, on both plans: print one, fill it in with a pen, and file it next to the printed ones.",
  "ageCheck.title": "Age check",
  "ageCheck.intro": "Scan the barcode on the back of a driver's license or state ID. You get one answer — a green check or a red check — and the app keeps nothing from the scan: no name, no number, no birthdate, nothing written down.",
  "ageCheck.scanPrompt": "Point the camera at the barcode on the back of the license or ID.",
  "ageCheck.categoryLabel": "What is being sold?",
  "ageCheck.category.alcohol": "Alcohol",
  "ageCheck.category.tobacco": "Tobacco",
