  "ageCheck.unreadable": "That code is not an ID barcode we can read. Try the barcode on the back of the license.",
  "ageCheck.checkAnother": "Check another",
  "ageCheck.back": "Back to product scanning",
  "ageCheck.keepsNothing": "Nothing from this scan is saved, sent, or recorded. The answer is all there is, and it is gone when you leave this screen.",
  "settings.ageLines.title": "Age lines",
  "settings.ageLines.description": "The age a customer must reach for each kind of sale, used by the age check on the Scan page. These lines are yours to set — set them to the law where your business is. The app starts at 21 for alcohol, 21 for tobacco, and 18 for other age-restricted goods.",
  "settings.ageLines.alcohol": "Alcohol — minimum age",
  "settings.ageLines.tobacco": "Tobacco — minimum age",
  "settings.ageLines.other": "Other age-restricted goods — minimum age",
  "plansLib.includes.ageCheck": "Age check by license scan — scan the back of an ID for a green or red check, and nothing from the ID is kept",
  "training.lessons.scanner-age-check.title": "Checking age with a license scan",
  "training.lessons.scanner-age-check.step1": "Some goods may only be sold to customers over a certain age. On the Scan page, open Age check, pick what is being sold — alcohol, tobacco, or other age-restricted goods — then scan the barcode on the back of the customer's driver's license or state ID.",
  "training.lessons.scanner-age-check.step2": "The answer is one of two checks. A green check means the customer is old enough and the sale can go ahead. A red check means they are not old enough for that line, or the ID is expired — either way, the sale must not happen.",
  "training.lessons.scanner-age-check.step3": "The app keeps nothing from the scan. No name, no license number and no birthdate is saved, sent or written down anywhere: the check answers the one question and is gone. There is no list of checked IDs to look back at — that is by design.",
  "training.lessons.scanner-age-check.step4": "The age lines belong to the owner, who sets them in Settings to the law where the business is. They can differ from place to place and from the app's starting lines, and the check always follows the owner's lines for the business you are in.",
  "training.lessons.scanner-age-check.step5": "If the code will not read, the screen says so plainly. Wipe the barcode and try again, or ask to see another ID. A code that is not an ID barcode never earns a green check.",
