  "plansLib.includes.ownTraining": "Add your own training — write your own trainings and quizzes for your team",
  "training.lessons.owner-own-training.title": "Adding your own training",
  "training.lessons.owner-own-training.step1": "At the very end of the Training page sits the Add your own training box. Open it, start a new training, and give it a title — your safety rules, your precautions, your way of doing things.",
  "training.lessons.owner-own-training.step2": "Write the training itself in the box, in your own words, or upload it as a file instead — a PDF, text, Word or OpenDocument file. Typed words replace a saved file, and a file replaces typed words.",
  "training.lessons.owner-own-training.step3": "Build its quiz underneath: as many questions as you like, multiple-choice and written-answer mixed freely. For a written question, write the answer you expect; for multiple choice, mark the correct one.",
  "training.lessons.owner-own-training.step4": "Set the passing line, and choose how written answers are judged: checked against your answer key nearly word for word, or sent to you to mark pass or send back. Then tick exactly which team members take this training — only they see it.",
  "training.lessons.owner-own-training.step5": "Each training you save stands on its own in the box, with its own questions, line and ticks, and you can add as many as you like. Results land in the box under each training; a training counts done only when the server has checked a passing run — or, in to-mark mode, when you mark it passed.",
